# owner: platform
"""Weekly timesheet lines, busiest workers first."""

from typing import Dict, List, Tuple

from hourglass.models import Shift

Tally = Tuple[int, int]
Item = Tuple[str, Tally]

# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    _check_shifts(shifts)
    totals = _tally(shifts)
    ranked = sorted(totals.items(), key=_busiest_first)
    return [_format_line(item) for item in ranked]

def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    if any(not shift.worker.strip() for shift in shifts):
        raise ValueError("a shift has a blank worker name")

def _tally(shifts: List[Shift]) -> Dict[str, Tally]:
    totals = {}
    for shift in shifts:
        count, minutes = totals.get(shift.worker, (0, 0))
        added = shift.span.minutes
        totals[shift.worker] = (count + 1, minutes + added)
    return totals

def _busiest_first(item: Item) -> Tuple[int, str]:
    name, (count, minutes) = item
    return (-minutes, name)

def _format_line(item: Item) -> str:
    name, (count, minutes) = item
    noun = "shift" if count == 1 else "shifts"
    hours = minutes / 60
    return f"{name}: {count} {noun}, {hours:.1f} hours"
